# Exec'd by make_mtt_entries.py. MikeTeachesTech "Practice Exams/2" = a transcription (exam.pdf) of NESA's
# HSC Software Engineering Sample Examination, with answers.pdf = NESA's official marking guidelines (21 May 2025).
SRC2 = 'MikeTeachesTech Practice Exam 2 (transcription of NESA HSC Software Engineering Sample Examination)'
B2 = dict(origin='MikeTeachesTech', reserved=False, publisher='MikeTeachesTech (Michael Grassi, CC BY-NC 4.0) / NESA',
          source_paper=SRC2, key_source='NESA Sample Examination marking guidelines (Practice Exams/2/answers.pdf)', issues=[], images=[])
def X(q, prompt, atype, marks, stimulus=None, **kw):
    e = {**B2, 'id': f'mtt-exam2-q{q}', 'source': f'{SRC2} Q{q} ({REPO}: Practice Exams/2/exam.pdf)', 'question_title': f'Practice Exam 2 Q{q}',
         'part': f'Question {q}', 'stimulus': stimulus, 'prompt': prompt, 'answer_type': atype, 'marks': marks}
    e.update(kw); out.append(e)
def O(texts, correct): return [{'letter': LETTERS[i], 'text': t, 'image': None, 'correct': i in correct} for i, t in enumerate(texts)]
def C(*rows): return [{'marks': str(m), 'criterion': t} for m, t in rows]
